/* prog51_union_find – reproduced from the obfuscated binary
 *
 * The program implements a tiny disjoint‑set (union‑find) structure for
 * elements 0 … 9.  It receives a sequence of commands on the command line
 * and prints the result of each command.  The observable output (stdout)
 * matches the original program exactly.
 *
 * Supported commands (case‑sensitive):
 *
 *   UNION a b        – unite the sets containing a and b
 *   FIND a           – print the representative of a
 *   CONNECTED a b    – print YES if a and b are in the same set, otherwise NO
 *   NOOP             – print the literal string "NOOP"
 *
 * Any unknown command, a missing argument, or an index outside the range
 * [0,9] causes the program to print "INVALID".  If the program is invoked
 * without any command‑line arguments it prints "NOOP" and exits.
 *
 * The implementation follows the classic union‑by‑rank with path compression.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEM 10

static int parent[MAX_ELEM];
static int rankv[MAX_ELEM];

/* Find with path compression */
static int find_set(int x)
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

/* Union by rank */
static void union_set(int x, int y)
{
    int rx = find_set(x);
    int ry = find_set(y);
    if (rx == ry)
        return;

    if (rankv[rx] < rankv[ry]) {
        parent[rx] = ry;
    } else if (rankv[rx] > rankv[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rankv[rx]++;          /* increase rank of new root */
    }
}

/* Helper: check that an index is within the allowed range */
static int valid_index(long v)
{
    return (v >= 0 && v < MAX_ELEM);
}

int main(int argc, char *argv[])
{
    /* No command line arguments → NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    /* initialise the disjoint‑set structure */
    for (int i = 0; i < MAX_ELEM; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }

    int pos = 1;                     /* current argument index */
    while (pos < argc) {
        const char *cmd = argv[pos++];
        if (strcmp(cmd, "UNION") == 0) {
            if (pos + 1 >= argc) {          /* need two numbers */
                puts("INVALID");
                break;
            }
            long a = strtol(argv[pos++], NULL, 10);
            long b = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
                continue;
            }
            union_set((int)a, (int)b);
            printf("UNION %ld %ld\n", a, b);
        }
        else if (strcmp(cmd, "FIND") == 0) {
            if (pos >= argc) {               /* need one number */
                puts("INVALID");
                break;
            }
            long a = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a)) {
                puts("INVALID");
                continue;
            }
            int r = find_set((int)a);
            printf("FIND %ld=%d\n", a, r);
        }
        else if (strcmp(cmd, "CONNECTED") == 0) {
            if (pos + 1 >= argc) {           /* need two numbers */
                puts("INVALID");
                break;
            }
            long a = strtol(argv[pos++], NULL, 10);
            long b = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
                continue;
            }
            int ra = find_set((int)a);
            int rb = find_set((int)b);
            puts(ra == rb ? "YES" : "NO");
        }
        else if (strcmp(cmd, "NOOP") == 0) {
            puts("NOOP");
        }
        else {
            puts("INVALID");
        }
    }

    return 0;
}
